import{_ as r}from"./chunks/0a89755d05ce1b8510a7.Bf9cnS6F.js";import{_ as t,C as o,o as l,c as i,j as p,a as n,E as s,a5 as u}from"./chunks/framework.DNkHA0lr.js";const I=JSON.parse('{"title":"聪明的创作者将如何在 2026 年赚钱（你还早）","description":"","frontmatter":{"title":"聪明的创作者将如何在 2026 年赚钱（你还早）","originalTitle":"How Smart Creators Will Make Money In 2026 (You’re Early)","date":"2025-05-22","originalUrl":"https://thedankoe.com/letters/how-smart-creators-will-make-money-in-2026-youre-early/","minutes":12,"sourceHash":"aa91936e21672584efc51d6aeb73c971aa7f7d388f292df0afaff73ba6bf540a","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/how-smart-creators-will-make-money-in-2026-youre-early/"}]]},"headers":[],"relativePath":"letters/how-smart-creators-will-make-money-in-2026-youre-early.md","filePath":"letters/how-smart-creators-will-make-money-in-2026-youre-early.md"}'),h={name:"letters/how-smart-creators-will-make-money-in-2026-youre-early.md"};function c(m,e,d,b,f,k){const a=o("ArticleMeta");return l(),i("div",null,[e[0]||(e[0]=p("h1",{id:"聪明的创作者将如何在-2026-年赚钱-你还早",tabindex:"-1"},[n("聪明的创作者将如何在 2026 年赚钱（你还早） "),p("a",{class:"header-anchor",href:"#聪明的创作者将如何在-2026-年赚钱-你还早","aria-label":'Permalink to "聪明的创作者将如何在 2026 年赚钱（你还早）"'},"​")],-1)),s(a),e[1]||(e[1]=u('<p>现在，创作者主要销售数字产品和服务。</p><p>教练辅导、课程、社群、训练营，以及订阅制会员。</p><p>这是有道理的。</p><p>它们有着巨大的利润率。它们可以由一个人规模化交付。它们比依赖平台收入或接受赞助提供更多自由。而且可以说，这是人们能购买的最具变革性的产品类型——从来没有一个时代，能让人以负担得起的价格，从站在技能前沿的人那里获得基于兴趣的教育，而由于教育影响行为，恰当的教育是唯一能改变你人生的东西。当然，也存在一些不良行为者。</p><p>现在，我对这一切将如何演变有一个预测。</p><p>如果你理解了这一点，未来几年你可能会获得一个竞争优势。</p><p>我的预测基于以下这些信念：</p><p><strong>1）信息永远不会是免费的</strong></p><blockquote><p>一方面，你所说的这一点，沃兹——是信息某种意义上想要变得昂贵，因为它是如此有价值——在正确的地方获得正确的信息，能彻底改变你的人生。另一方面，信息又几乎想要变得免费，因为把它传播出去的成本一直在不断降低。所以你就有了这两种力量互相对抗。</p><p>——斯图尔特·布兰德（Stewart Brand）采访苹果公司史蒂夫·沃兹尼亚克（Steve Wozniak）</p></blockquote><p>信息并不“想要”免费，因为信息本身没有意愿。</p><p>人们希望信息是免费的，是因为他们不明白信息本身就是劳动。</p><p>虽然这话到这个地步听起来可能有点老生常谈，但如果人们不付钱，他们就不会认真关注。只有和金钱关系不健康的人，才会为付钱获取关键信息而感到为难。</p><p>当然，信息存在的时间越长，就越不值钱。它会变成常识，AI 也会基于最流行或最相关的内容进行训练，但仍有另一类信息，在可预见的未来会保持其价值。</p><p>这正是创作者登场的地方。</p><p>创作者经营的是个人化信息（文字、音频、视频），而且这种局面会持续下去。</p><p>问题在于，如布兰德在上面那句话中向沃兹尼亚克指出的那样，要让正确的信息出现在正确的地方。</p><p><strong>2）AI 永远不会开箱即给你最好的答案</strong></p><p>不是 AI 不如你好。</p><p>而是你还不够好，还没能让 AI 比你更强。</p><p>因为如果你让 ChatGPT 给你写一本书，它会写，但那本书不值得一读。</p><p>如果你既擅长写书，又擅长提示工程（大体上就是给 AI 清晰的指令），那你大概能比以前快得多地写出一本很棒的书，<em>而且它依然出自你自己的知识，而不是 AI 的。</em></p><p>AI 只有在获得足够多上下文的情况下，才能在高度依赖情境的领域（比如营销、写作、设计，或任何非机械性的工作）中发挥效力。以至于此时提供知识的已经不再是 AI，AI 做的其实是繁琐的执行工作。</p><p>这一点会很容易理解。</p><p><strong>3）课程是静态的</strong></p><p>目前有 3 种类型的报价（offer）。</p><p>自己动手做。和你一起做。为你代做。</p><p>这些是社交媒体诞生以来创作者一直在销售的东西。有人以营销之类的技能做自由职业。有人以健康之类的兴趣做教练辅导。有人如果想在产品线里加入一款低价产品，就卖课程。</p><p>但这几种方式各有各的缺点。</p><p>课程是静态信息，必须被正确解读才能起作用。</p><p>自由职业通常缺乏成就感，因为你是在为别人的项目工作，而不是为自己的。</p><p>教练辅导则要求你投入大量时间，或者如果想要规模化，就需要一个不断扩大的团队。</p><p>但如果 AI 现在能让你把这三者合而为一呢？</p><p>如果一款数字产品既能提供基于你自己独特知识的教育，<em>又</em>能提供执行呢？</p><h2 id="数字产品的未来" tabindex="-1">数字产品的未来 <a class="header-anchor" href="#数字产品的未来" aria-label="Permalink to &quot;数字产品的未来&quot;">​</a></h2><p>我这些年创建过几款数字产品。</p><p>我的下一款产品将是一个<a href="https://stan.store/thedankoe/p/build-a-profitable-personal-brand-in-30-days" target="_blank" rel="noreferrer">打造个人品牌的 30 天挑战</a>。</p><p>（因为我想在我们尝试将这个理念作为一项功能——共享带有自定义提示的工作空间——内置到 Kortex 之前，先测试一下这个理论，赶上这波浪潮）。</p><p>现在，让我们来跑一遍场景。</p><p>想象我这款数字产品有两个组成部分：</p><ul><li><strong>教育</strong> —— 以易于消化的方式呈现出来的课程体系或知识。</li><li><strong>执行</strong> —— 基于这份特定知识构建的 AI 提示词，让你能更快地执行。</li></ul><p>这两者单独存在时，都不如它们结合在一起那么有价值。</p><p>让 AI 替你完成任务，并不会教会你如何自己完成这项任务，所以当 AI 不可避免地只给出一份初稿时，你不知道该如何做出一份真正能用的最终稿。AI 解决不了迭代或缺乏成果的问题（除非你知道该在<em>哪个方向</em>引导它）。</p><p>这就是为什么“氛围编程者（vibe coders）”现在还搞不出什么复杂的东西。</p><p>他们并不在高层次上理解编程，所以一旦碰到 bug，他们就只能开始学编程，或者卡在原地，因为他们把自己的能动性外包出去了。即便人们能用自然语言编写出一整个应用程序，也不代表人们就会去用它。换句话说，你仍然需要去学习。</p><p>而当你只拥有教育部分时，很难把那些知识运用到自己的具体情境中。很多人在学习课程时遇到困难，是因为他们试图照搬老师的做法，却没意识到自己独特的处境会改变那份教育应该如何被应用。</p><p>这正是两者结合能够蓬勃发展之处。</p><p>AI 非常擅长收集你的个人背景信息，尤其是在被提示这样做的时候，这样它就能把这些因素纳入考虑，去完成任务。</p><p>如果你是在跟我学习如何打造个人品牌，那里面有很多变动的变量。你需要提炼出自己的信念、观点、兴趣、想法等等。AI 无法从你的脑子里把这些直接拽出来，但它可以帮助引导你的思维，让你自己想出这些东西。</p><p>这就是为什么课程的完成率和成功率如此之低。</p><p>让我把这一点说得更清楚：</p><p>想象一门 YouTube 课程。</p><p>它教你：</p><ul><li>如何产生具有病毒式传播潜力的创意</li><li>如何设计并迭代封面缩略图的创意</li><li>如何构建 YouTube 脚本大纲和关键要点</li><li>如何设计钩子和开场，以降低观众流失</li><li>如何为节奏、B 卷、主镜头和画面设计做视频分镜</li></ul><p>你需要理解的是：这里没有一种“最佳方式”。</p><p>如果你在没有上下文的情况下让 AI 去做这些事，它会给你一些能在网上找到的泛泛信息。</p><p>但关于 YouTube，以及大多数高度依赖情境的（非机械性的）领域，问题在于“什么方法有效”这件事变化得相当频繁。没有哪个 YouTuber 和另一个完全一样，然而他们似乎都能以各自的方式获得某种成功。这意味着，即便是专门针对 YouTube 的 AI 软件，也会有其缺陷，因为它大概是基于<em>某一种</em>最佳实践构建的。如果所有人都用那同一个 AI 工具，产生的结果就会越来越少。</p><p>所以，对于这门 YouTube 课程，创作者要用他们自己的<em>思维、模型和方法</em>把它构建出来。</p><p>然后，当他们把上面每一条要点（比如创意生成、大纲、脚本撰写等）都转化成一个提示词时，一件神奇的事情就发生了。</p><p>你不仅拥有了教育，还拥有了执行！</p><p>你意识到这有多离谱吗？</p><p>一门 YouTube 课程不再只是一门课程了。它成了创作者心智的一部分，<em>而且这部分心智能够自行运作。</em></p><p>你，作为个人，可以购买这一部分他们的心智，研读那份“操作手册”，赋予它你自己的背景信息，然后它就<em>替你完成这项工作。</em></p><p>它给你创意，你选一个，它引导你完成大纲，你编辑修改，它按照你自己的声音风格生成脚本，而且，说实话，将来某个时候 AI 甚至能创作出整段视频，听起来像你，看起来也是你的风格。</p><p>这依然是<em>你</em>在创作这个视频，你只是做的工作变少了。</p><p>这不是 AI 垂圾内容（AI slop），因为它拥有<em>上下文。</em></p><p>如果你想看看这在实际中是怎么运作的，<a href="https://youtu.be/4E9rO6FDUwo" target="_blank" rel="noreferrer">看看我在 Kortex 频道做的这个视频。</a></p><p>那一家公司的内容团队呢？你不需要把某个人雇来做自由职业者，因为他们即使不在场，也能替你完成工作。</p><p>像健身教练这类工作呢？在这种情况下，他们不能替你把训练本身做了？没问题，他们仍然可以拥有能生成定制训练计划、营养方案，以及每日打卡以追踪你的进展、减重情况，或者其他任何指标的提示词。</p><p>你卖的不再是一门课程了。</p><p>你卖的是一套完整的解决方案——一个个性化、专属于你的系统，这是 AI 永远不会开箱即给的，因为它需要被专门训练才能做到——而这样的系统更有可能带来真正的成果。</p><p>信息的价值并没有在下降，而是在急剧上升。</p><h2 id="如何打造一款-ai-优先-的产品" tabindex="-1">如何打造一款“AI 优先”的产品 <a class="header-anchor" href="#如何打造一款-ai-优先-的产品" aria-label="Permalink to &quot;如何打造一款“AI 优先”的产品&quot;">​</a></h2><p>如果你是一名创作者，或者你想成为一名创作者，你能做的最好的事，就是学会如何把你的知识转化为一个提示词。</p><p>如果你是初学者，并且把这件事做好了，恭喜你，你现在就有了第一款可以立刻开始销售的产品！</p><p>以下是我会照做的确切步骤：</p><h3 id="_1-记录你的流程" tabindex="-1">1）记录你的流程 <a class="header-anchor" href="#_1-记录你的流程" aria-label="Permalink to &quot;1）记录你的流程&quot;">​</a></h3><p>打开一份笔记或文档来写。</p><p>如果你想让这件事更轻松一点，可以在<a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex</a>里完成，这样当我们把这份文档转化成提示词时，你就可以在 AI 聊天中引用它。你可以在 ChatGPT 之类的工具之间来回复制粘贴，但 Kortex 内置了 ChatGPT 的模型和其他所有模型，所以你可以针对不同用例选择不同的模型。</p><p>从这里开始，<em>把自己当作是在向另一个人下达详细指令，让他们能照着做出你所做的事。</em></p><p>这会花一些时间。</p><p>如果你是一名 YouTuber，那你需要为你流程中的每一步都创建一份文档。回头看看前面的要点列表，把每一条都展开详述。</p><p>以创建一段 YouTube 开场为例，<a href="https://app.kortex.co/public/document/eff80eec-769f-479d-8a00-e1556aac6c6e" target="_blank" rel="noreferrer">它可能是这样的</a>（放在一篇文档链接里，因为内容又长又详细）。</p><p>当然，你几乎可以对任何任务这样做。如果你以前从没做过这件事，可能会觉得有点难。你实际上是在学习如何管理和教导一名员工（AI），这需要时间。</p><p>但是，你只需记录一次，就能永久使用。</p><p>而且，你也可以把这份记录当作你课程大纲的框架。</p><p>前期需要投入一些工作，但回报很大。</p><p>这是一项值得专注的高杠杆活动。</p><h3 id="_1-5-借用别人的流程" tabindex="-1">1.5）借用别人的流程 <a class="header-anchor" href="#_1-5-借用别人的流程" aria-label="Permalink to &quot;1.5）借用别人的流程&quot;">​</a></h3><p>对于你自己的东西，我建议你手动来做这件事。</p><p>但出于价值和教育的考虑，这里还有一件你可以做的事：</p><ul><li>选定一个你想完成的任务</li><li>在 YouTube 上找一位在视频中教授这项技能的专家</li><li>或者，找一本教这个的书的 PDF</li><li>把它喂给 AI（你可以链接一段 YouTube 视频，或者把 PDF 上传到 Kortex）</li><li>让 AI 把详细的操作步骤拆解出来</li><li>把它保存为一份文档，以便在第 2 步中引用</li></ul><p>这正是我处理上面那份 YouTube 开场说明时所做的 😉</p><p>我找到了一个教这个的视频，然后让 AI 把它拆解出来。</p><p>我有一份<a href="https://stan.store/thedankoe/p/mini-course-how-i-systemize-my-life-with-ai" target="_blank" rel="noreferrer">免费的 AI 迷你课程</a>，里面讲了很多这方面的例子。</p><h3 id="_2-把每一部分都转化为一个提示词" tabindex="-1">2）把每一部分都转化为一个提示词 <a class="header-anchor" href="#_2-把每一部分都转化为一个提示词" aria-label="Permalink to &quot;2）把每一部分都转化为一个提示词&quot;">​</a></h3><p>值得花 30-40 个小时自己去研究提示工程。</p><p>我显然无法在这里把一切都解释清楚。</p><p>正因为如此，我想给你一个我自己在用的捷径。</p><p>根据任务的不同，我喜欢把我的提示词（prompt）分成两个阶段来构建。</p><ul><li><strong>阶段 1</strong> = 上下文收集阶段，通过采访用户来获取执行任务所需的相关信息。</li><li><strong>阶段 2</strong> = 执行阶段，利用用户提供的信息来完成任务。</li></ul><p>如果任务是类似创建一个 YouTube 开场白这样的事情，那你显然需要用户的上下文。你需要他们想要转化成视频的创意，还需要一份语音风格分析作为参考，好让它听起来像是他们本人的声音。</p><p>最好你还有一个创意生成提示词。这样，你就可以把那个提示词的输出结果，喂给 YouTube 开场白提示词。</p><p>这些任务在某种程度上，是一个个建立在前一个基础之上的。</p><ul><li>首先，你有一个创意生成提示词，它收集关于你兴趣的上下文，然后输出高表现的话题</li><li>然后，你把其中一个话题作为上下文，喂给 YouTube 开场白提示词，它还会收集你想使用的关键点的上下文。</li><li>然后，你把这些作为上下文，喂给大纲提示词。</li><li>然后，你把这些作为上下文，喂给脚本提示词。</li></ul><p>简而言之，你将会创建相当多的提示词，来把整个流程封装起来。</p><p>好了，捷径来了。</p><p>我有一个能创造出令人惊叹的提示词的提示词。</p><p>所以，你告诉它你想完成什么任务，给它这个任务的指令，然后让它把提示词的输出结构分成两个阶段。</p><p>你可以直接复制<a href="https://app.kortex.co/public/document/83651c0d-dfd3-4e6c-9821-c9c41b2a3ddc" target="_blank" rel="noreferrer">这里的提示词</a>，或者在 Kortex 里进入 <strong>Chat → Create Incredible AI Prompts</strong>，让它帮你完成这件事。我喜欢用 Gemini 2.5 Pro 或 Claude 3.7 Sonnet 来做这件事。</p><p>下面是这个用来创建提示词的提示词长什么样。</p><p><img src="'+r+'" alt=""></p><p>注意我是以文档的形式提供指令，并把它构建成两个阶段。<a href="https://app.kortex.co/public/document/d1ac7b33-83f8-4af6-886a-9b9d867d0318" target="_blank" rel="noreferrer">这是那个提示词的输出结果。</a></p><p>这样做美妙的地方在于，你可以把这些提示词保存为文档，这样你就能随时组织和引用它们了。</p><h3 id="_3-自己使用并迭代" tabindex="-1">3）自己使用并迭代 <a class="header-anchor" href="#_3-自己使用并迭代" aria-label="Permalink to &quot;3）自己使用并迭代&quot;">​</a></h3><p>你可能以为到这里就结束了。</p><p>但并没有。</p><p>我知道你希望 AI 是那种全能魔法般的东西，替你把所有活都干完，但如果你想让它变得好用，事情并不是这样运作的。</p><p>把这当作初稿来看。</p><p>这跟为你的生活创建任何一套系统是一样的道理。</p><p>你创建一套routine，试用一周，注意到哪些地方效果不好，然后尝试新的方法，直到取得很棒的结果。健康、写内容等等，都是这个道理。</p><p>接下来几周，你的任务就是自己使用你创建的这些提示词，评估它们有多好，然后不断修改提示词，直到结果达到你自己水平的80%到90%那么好。</p><p>到那时，你才有值得拿给别人的东西。</p><p>就目前而言，AI 始终需要有人来评估和编辑它的输出。</p><p>如果你让它吐出一份 YouTube 脚本，当然，你可以直接用，也能看到不错的效果……可能比大多数人做得都好，但你还是要把它当作一份草稿，加上你自己的润色。</p><h3 id="_4-创建文档" tabindex="-1">4）创建文档 <a class="header-anchor" href="#_4-创建文档" aria-label="Permalink to &quot;4）创建文档&quot;">​</a></h3><p>恭喜你。</p><p>现在你已经拥有了一个提示词库，可以用于自己的工作，也可以作为产品给别人。</p><p>现在，你需要创建课程内容的部分。</p><p>你需要教会他们如何使用这些提示词，以及他们需要了解这项任务的哪些知识。</p><p>幸运的是，你已经把你的流程梳理好了。</p><p>你只需要在此基础上扩展并组织成一个产品的形式，把某个人从A点带到B点。</p><p>如果你想深入了解，我在这里写了一篇<a href="https://thedankoe.substack.com/p/mega-guide-how-to-create-your-first" target="_blank" rel="noreferrer">关于创建数字产品的超级指南</a>。</p><p>不再多花一个小时展开，这里是我创建数字产品会采取的做法：</p><ul><li>购买一个看起来效果不错的别人的产品</li><li>把它的所有内容分别保存为 Kortex 里的独立文档</li><li>让 AI 分析这个产品的结构和模式（为什么它效果好）</li><li>结合你上面学到的东西，把这变成一个提示词</li><li>把你自己产品的细节喂给它</li><li>让它引导你完成自己产品的创建</li></ul><p>你在这里学到的，不仅仅是用来创建产品的。</p><p>这是一种与 AI 打交道的思维方式。</p><p>这就是你教 AI 完成你想实现的任何任务的方法。</p><p>我就把这个留给你了。</p><p>感谢阅读。</p><p>—— Dan</p><p>如果你想深入了解：</p><ul><li>&quot;30天打造盈利的个人品牌&quot;挑战将于6月16日上线。目前<a href="https://stan.store/thedankoe/p/build-a-profitable-personal-brand-in-30-days" target="_blank" rel="noreferrer">早鸟优惠</a>。</li><li>Substack 上最新的付费文章是一篇<a href="https://thedankoe.substack.com/p/mega-guide-how-to-create-your-first" target="_blank" rel="noreferrer">打造数字产品的超级指南</a>，以及<a href="https://thedankoe.substack.com/p/how-to-write-persuasive-landing-pages" target="_blank" rel="noreferrer">如何为该产品撰写销售页面</a>。下一篇将是关于发布策略的内容。</li><li>Claude 4 刚刚发布，我们将把它以及其他所有 AI 模型都整合<a href="https://kortex.co/" target="_blank" rel="noreferrer">进 Kortex</a>——一款笔记和 AI 工作流软件。</li></ul><hr><p><a href="/en/letters/how-smart-creators-will-make-money-in-2026-youre-early">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',144))])}const g=t(h,[["render",c]]);export{I as __pageData,g as default};
